content.text:
{
  "name": "AT2L0 固体衰减器",
  "name_en": "AT2L0 Solid Attenuator",
  "manufacturer": "",
  "description": "一种电动固体衰减器，含 18 片滤片和 1 个检查镜，用于 LCLS-II XTES 束线中按设定透过率调节 X 射线束强度，并帮助保护下游光学元件和实验样品。",
  "description_en": "A motorized solid attenuator with 18 filters and one inspection mirror, used on the LCLS-II XTES beamline to adjust X-ray beam intensity to a desired transmission and help protect downstream optics and experiments.",
  "tag_hints": [
    "X-ray attenuation",
    "solid attenuator",
    "beam transmission control",
    "motorized filters",
    "inspection mirror",
    "LCLS-II XTES",
    "beamline protection"
  ],
  "actions": [
    {
      "action_name": "auto-calc_lightpath_state",
      "description": "计算衰减器对光路的状态",
      "description_en": "Calculate the attenuator lightpath state."
    },
    {
      "action_name": "auto-clear_errors",
      "description": "清除衰减器错误并恢复可运动状态",
      "description_en": "Clear attenuator errors and return it to a movable state."
    },
    {
      "action_name": "auto-format_status_info",
      "description": "整理并显示衰减器状态信息",
      "description_en": "Format and display attenuator status information."
    },
    {
      "action_name": "auto-print_errors",
      "description": "输出当前错误摘要",
      "description_en": "Print the current error summary."
    },
    {
      "action_name": "auto-actuate_value",
      "description": "执行当前选定的衰减器配置",
      "description_en": "Apply the currently selected attenuator configuration."
    },
    {
      "action_name": "auto-set_energy",
      "description": "设置用于衰减计算的束流能量",
      "description_en": "Set the beam energy used for attenuation calculations."
    },
    {
      "action_name": "auto-transmission",
      "description": "获取衰减器的透过率",
      "description_en": "Get the attenuator transmission."
    },
    {
      "action_name": "auto-inserted",
      "description": "获取衰减器是否插入光束路径",
      "description_en": "Get whether the attenuator is inserted into the beam path."
    },
    {
      "action_name": "auto-removed",
      "description": "获取衰减器是否移出光束路径",
      "description_en": "Get whether the attenuator is removed from the beam path."
    },
    {
      "action_name": "auto-insert",
      "description": "将衰减元件插入光束路径",
      "description_en": "Insert the attenuation elements into the beam path."
    },
    {
      "action_name": "auto-remove",
      "description": "将衰减元件移出光束路径",
      "description_en": "Remove the attenuation elements from the beam path."
    },
    {
      "action_name": "auto-stage",
      "description": "准备衰减器进入操作状态",
      "description_en": "Prepare the attenuator for operation."
    },
    {
      "action_name": "auto-subscribe",
      "description": "订阅衰减器状态更新",
      "description_en": "Subscribe to attenuator status updates."
    },
    {
      "action_name": "auto-get_active_config",
      "description": "获取当前启用的滤片配置",
      "description_en": "Get the currently active filter configuration."
    },
    {
      "action_name": "auto-get_best_config",
      "description": "获取满足目标衰减条件的最佳滤片配置",
      "description_en": "Get the best filter configuration for the target attenuation."
    },
    {
      "action_name": "auto-get_moving_status",
      "description": "获取衰减器是否正在运动",
      "description_en": "Get whether the attenuator is moving."
    },
    {
      "action_name": "auto-calculate",
      "description": "计算给定能量和目标衰减所需的滤片组合",
      "description_en": "Calculate the filter combination needed for a given energy and target attenuation."
    },
    {
      "action_name": "auto-setpoint",
      "description": "获取目标透过率设定值",
      "description_en": "Get the desired transmission setpoint."
    },
    {
      "action_name": "auto-readback",
      "description": "获取实际透过率读数",
      "description_en": "Get the actual transmission readback."
    },
    {
      "action_name": "auto-actuate",
      "description": "获取应用当前配置的执行信号",
      "description_en": "Get the apply-configuration actuation signal."
    },
    {
      "action_name": "auto-get_lightpath_state",
      "description": "获取光路状态",
      "description_en": "Get the lightpath state."
    },
    {
      "action_name": "auto-as_out_row",
      "description": "将状态表示为移出光束的配置行",
      "description_en": "Represent the state as an out-of-beam configuration row."
    },
    {
      "action_name": "auto-as_in_row",
      "description": "将状态表示为插入光束的配置行",
      "description_en": "Represent the state as an in-beam configuration row."
    },
    {
      "action_name": "auto-filter_index",
      "description": "获取滤片索引",
      "description_en": "Get the filter index."
    },
    {
      "action_name": "auto-is_inserted",
      "description": "获取该滤片或刀片是否处于插入状态",
      "description_en": "Get whether the filter or blade is in the inserted state."
    },
    {
      "action_name": "auto-is_moving",
      "description": "获取该滤片或刀片是否正在运动",
      "description_en": "Get whether the filter or blade is moving."
    },
    {
      "action_name": "auto-setup_mode",
      "description": "进入衰减器配置模式",
      "description_en": "Enter attenuator setup mode."
    }
  ]
}

